// Replaces the default counter test generated by `flutter create`.
import 'package:flutter_test/flutter_test.dart';
import 'package:obd_saga/obd/elm327.dart';
import 'package:obd_saga/obd/fuel.dart';
import 'package:obd_saga/obd/pids.dart';
import 'package:obd_saga/settings.dart';

void main() {
  test('parses RPM response', () {
    final bytes = Elm327.mode01Bytes('410C1AF8', Pids.rpm);
    expect(bytes, [
      [0x1A, 0xF8]
    ]);
    expect(Pids.byId[Pids.rpm]!.decode(bytes.first), 1726);
  });

  test('coolant and fuel level', () {
    expect(Pids.byId[Pids.coolant]!.decode([0x7B]), 83);
    expect(Pids.byId[Pids.fuelLevel]!.decode([0xFF]), 100);
  });

  test('errors return no data', () {
    expect(Elm327.mode01Bytes('NO DATA', Pids.rpm), isEmpty);
    expect(Elm327.mode01Bytes('?', Pids.rpm), isEmpty);
  });

  test('multi-ECU support bitmask lines', () {
    final r = Elm327.mode01Bytes('4100BE3EB813\n4100 80000000', 0x00);
    expect(r.length, 2);
  });

  test('MAF fuel rate', () {
    final s = AppSettings();
    // 10 g/s air -> 10/14.7 g/s fuel -> ~3.31 L/h
    final lph = FuelCalc.litresPerHour(
        FuelSource.maf, {Pids.rpm: 2500, Pids.maf: 10}, s)!;
    expect(lph, closeTo(3.31, 0.02));
    expect(FuelCalc.litresPer100(lph, 60), closeTo(5.52, 0.05));
  });

  test('speed-density fuel rate is sane at idle', () {
    final s = AppSettings();
    final lph = FuelCalc.litresPerHour(FuelSource.speedDensity,
        {Pids.rpm: 800, Pids.map: 32, Pids.iat: 35}, s)!;
    // A 1.3 L engine idles at roughly 0.5–1 L/h.
    expect(lph, inInclusiveRange(0.3, 1.2));
  });
}
